        "평가사유": "[화제성 5점] 확정 → 개념미술 선구자 솔 르윗 국내 첫 대규모 개인전. 미술계 파급은 크지만 일반 대중 인지도는 낮은 작가로, 블록버스터 명화전급 화제는 아님. [독창성 5점] 국내 첫 개인전이라는 희소성은 인정되나 도쿄도현대미술관에서 출발한 **순회전**이며 공개 전시로 독점 취재권이 없다 — 실무자 원칙에 따라 상향 제한. [근접성 7점] 확정 → 용산 수도권 + 2026-09-01~2027-02-28 약 6개월 장기 운영으로 관람 접근성 상향(기존 6점→7점). 사전예약제. [영향성 6점] 개념미술 담론·기업 미술관 후원(불가리) 등 의제화 여지, 다만 관람 규모는 대중 전시 대비 제한적. [종합] 강점: 국내 첫 대규모 회고·6개월 장기·수도권 접근성. 약점·리스크: 순회전이라 기획 독점성 없음, 벽면 드로잉 일부는 지시문에 따른 재제작이므로 '원작 진품' 프레임을 그대로 쓰면 오류. 편성: 장기간이라 편성 유연성이 높아 시즌 아무 때나 배치 가능.",
