        "평가사유": "[화제성 9점] (확정 →) 롤드컵 8강·4강은 국내 e스포츠 화제성이 정점에 이르는 구간이고, 4년 만의 미국 개최다. 단판이 아닌 5전제 토너먼트라 경기당 화제 밀도도 가장 높다. (추정 →) LCK 팀의 진출 여부는 스위스 스테이지 결과에 달렸으나, LCK는 매 시즌 복수 팀이 녹아웃에 오른 이력이 있어 진출 개연성이 높다. 실무자가 LCK 관련 이벤트에 화제성을 유지한 기준을 적용하고, 스위스 스테이지(화제성 8점)보다 한 단계 높게 본다.\n[독창성 6점] (앰부시·차별성 관점) 라이엇 공식 무료 송출이라 중계 독점은 불가하다. 다만 국내 팬덤 규모가 커 연계 콘텐츠 가치가 높고, 실무자 원칙5(자사 연관 구단 출전 시 독창성 가점 — 한화생명e스포츠의 LCK 시드 진출 가능성)를 반영해 스위스 스테이지와 동일한 6점을 유지한다.\n[근접성 5점] (시차 관점) 미국 텍사스 앨런 개최로 한국시간 새벽~오전 경기다. 실무자 원칙1이 걸리지만 LCK 팀 출전이 시차 불리를 일부 보완한다. 스위스 스테이지(근접성 5점)와 동일.\n[영향성 6점] (자사 매체 신뢰도 기여 관점) 젊은층 대상 파급이 크고 e스포츠 콘텐츠는 우리 매체의 타깃 확장에 기여한다.\n[종합] 강점: 국내 e스포츠 최대 화제 구간 + 자사 연관 구단 진출 가능성 + 5전제 서사. 약점·리스크: LCK 팀 전멸 시 화제성이 급감하고, 새벽 시차와 중계 비독점이 겹친다. 결승(11-14 뉴욕)은 시작일이 윈도우 밖이다. 편성: 한국 팀 경기 중심 다시보기·선수 특집이 현실적이다.",
