        "평가사유": "[화제성 4점] (확정 →) 총상금 1,550만 달러 규모의 여자 테니스 시즌 최종전으로, 상금만 보면 그랜드슬램급이다. 단식 8명·복식 8팀 라운드로빈 방식이다. (추정 →) 그러나 한국 선수 진출 가능성이 사실상 없고 진출자 자체가 미확정이다. 실무자 원칙4를 적용해 4점으로 제한한다. 실무자 원칙5(해외 권위·상금 규모는 국내 인지도로 환산)도 함께 걸린다.\n[독창성 4점] (앰부시·차별성 관점) WTA 공식 송출로 중계 독점이 불가하고 국내 채널 편성도 미확정이다. 시즌 최종전이라는 희소성만 반영해 4점.\n[근접성 3점] (시차 관점) 사우디 리야드 개최로 한국시간 심야 경기다. 실무자 원칙1 적용. 리야드 개최에 대한 국내 관심도 낮다.\n[영향성 3점] (자사 매체 신뢰도 기여 관점) 국내 여자 테니스 저변이 좁아 파급과 신뢰도 기여가 모두 제한적이다.\n[종합] 강점: 여자 테니스 시즌 최종전이라는 위상과 최대 상금. 약점·리스크: 한국 선수 무관, 심야 시차, 국내 중계 미확정, 진출자 미확정. 편성: 우선순위 하위.",
