        "평가사유": "[화제성 4점] (확정 →) 5개 자치구 코스 도입 50주년 기념 대회이고 참가자 5만여 명 규모로 세계 최대 마라톤이다. 월드 마라톤 메이저스 시즌 마지막 대회라는 위상도 있다. (추정 →) 그러나 한국 엘리트 출전이 확인되지 않았고 엘리트 명단도 미발표다. 실무자 원칙4에 따라 제한한다. 다만 50주년이라는 기념성은 인정해 베를린·시카고 마라톤(화제성 3점)보다 1점 높게 본다.\n[독창성 3점] (앰부시·차별성 관점) 국내 중계가 확정되지 않았고 독점 취재·중계 확보 여지가 없다. 실무자 원칙2에 따라 하단.\n[근접성 2점] (시차 관점) 미국 동부 개최로 한국시간 심야~새벽이고, 단일일 이벤트라 편성 대안도 없다. 베를린·시카고 마라톤(근접성 2점)과 동일하다.\n[영향성 3점] (자사 매체 신뢰도 기여 관점) 러닝 인구 증가와 맞물린 소재이나 우리 채널 신뢰도 기여는 약하다.\n[종합] 강점: 50주년이라는 기념성 + 세계 최대 규모. 약점·리스크: 새벽 시차, 국내 중계 미확정, 한국 엘리트 출전 미확인, 단일일 이벤트. 편성: 러닝 트렌드 기획의 소재로만 가치가 있다.",
