        "분류": "소설",
        "영향성": 6,
        "저자역자": "저자 : 정지아",
        "평가사유": "[화제성 7점] (확정 →) 정지아는 『아버지의 해방일지』로 검증된 작가이고, 이 작품은 그 이후 **처음 내는 장편소설**이다. 매거진창비 온라인 연재물로 먼저 공개돼 독자 기반이 형성된 상태이며 알라딘 주목신간(ItemNewSpecial)에 등재됐다. (추정 →) 다만 전작만큼의 전국민적 화제까지는 검색으로 확인되지 않아 8점 이상 근거는 부족하다.\n[독창성 6점] (독점성·희소성 관점) 평균 연령 70대 시골 마을에 30대 레즈비언 커플이 이사 오며 벌어지는 소동과 화해를 다뤄, 지방소멸과 성소수자라는 두 의제를 겹쳐 놓은 설정은 국내 소설에서 희소하다. 저자 인터뷰·북토크 확보 여지도 있다. 다만 창비 대형 출간이라 서점·언론이 일제히 다룰 것이므로 독점 확보는 어렵다.\n[근접성 8점] (한국 독자 친숙도·시의성) 한국 작가의 한국 배경 소설이고, 지방소멸·고령화·성소수자 수용이라는 주제가 현재 한국 사회 현안과 직결된다. 창비 유통망으로 대형 서점 매대 노출도 확실하다.\n[영향성 6점] (판매·의제화·영상화) 전작이 문학 담론과 판매 양쪽에서 성과를 낸 이력이 있어 문학면 의제화 가능성이 높고, 소재 특성상 영상화 논의로 이어질 여지도 있다. (추정 →) 다만 영상화 발표는 확인되지 않았다.\n[종합] 강점: 검증된 작가의 첫 장편 복귀 + 시의적 소재 + 연재로 형성된 독자 기반. 약점·리스크: 전작과의 비교 부담이 크고, 성소수자 소재는 일부 독자층 반발 가능성이 있다. 편성: 저자 인터뷰를 확보하면 이번 회차 도서 코너의 앵커로 쓸 수 있다.",
        "출판사": "(주식회사)창비",
        "순위": 1,
        "장르형태": "국내문학(장편소설)",
        "개요": "한국현대사의 굵은 상흔을 남도의 구수한 입말과 뜨거운 인간애로 풀어내며 40만 독자의 마음을 사로잡은 『아버지의 해방일지』(창비 2022). 그 신드롬의 주인공 정지아가 4년 만의 신작 장편소설 『찌니주의보』로 돌아왔다.",
