        "근접성": 8,
        "평가사유": "[화제성 8점] (확정→) 원작 영화 〈오디세이〉(크리스토퍼 놀런)는 전 세계 69개국 박스오피스 1위, 글로벌 오프닝 2억 6,406만 달러로 놀런 연출작 역대 최고 오프닝, 개봉 2주 6억 3,960만 달러로 손익분기 돌파(YTN·머니투데이). 국내 개봉은 8월 5일로 확정되고 개봉 D-7 사전 예매 15만 장 돌파(놀런 감독 역대 최고, 스타뉴스). 각본집 출간일(8/19)이 국내 개봉 2주 뒤로 화제 정점과 겹침. 알라딘 판매지수 1,210. [독창성 4점] 공식 각본집이라 콘텐츠 자체 희소성은 있으나, 서점·언론·영화 채널이 일제히 다룰 소재이고 독점 인터뷰·단독 공개 요소가 없음. [근접성 8점] 국내 개봉 직후 최대 화제작 + 놀런 팬덤·일반 관객 모두 포괄, 대형 서점 매대 노출 확실. [영향성 7점] 영화 흥행과 직결된 판매 파급, 영화·창작 기획(각본 읽기·연출 분석) 연계 여지 큼. 단 사회적 의제화는 아님. [종합] 강점: 확정된 글로벌 메가히트 + 국내 개봉 타이밍 정합 / 약점·리스크: 독점성 없어 타 매체와 동시 소비, 개봉 후 평가 변동 시 화제 감쇠 / 편성: 배치 최우선. 8월 영화 특집과 묶을 것.",
